(() => {
  const BANDS = [{ fromCents: 0, toCents: 1e6, ratePercent: 0 }, { fromCents: 1e6, toCents: 5e6, ratePercent: 2 }, { fromCents: 5e6, toCents: Infinity, ratePercent: 3 }];
  function roundHalfCent(units) {
    const q = Math.floor(units / 100);
    const r = units - q * 100;
    if (r > 50) return q + 1;
    if (r === 50) return q + 1;
    return q;
  }
  function calculateQuarterlyRebate(input) {
    const obj = input !== null && typeof input === "object" ? input : {};
    for (const key of Object.keys(obj)) {
      if (key !== "quarterlyPurchases") throw new Error("unknown field: " + key);
    }
    const x = obj.quarterlyPurchases;
    if (typeof x !== "number" || !Number.isFinite(x)) throw new Error("invalid field: quarterlyPurchases");
    const cents = Math.round(x * 100);
    let totalUnits = 0;
    const bands = BANDS.map((b) => {
      const upper = Math.min(cents, b.toCents);
      const portionCents = Math.max(0, upper - b.fromCents);
      const units = portionCents * b.ratePercent;
      totalUnits += units;
      return { rate: b.ratePercent / 100, portion: portionCents / 100, amount: units / 1e4 };
    });
    const rebateCents = roundHalfCent(totalUnits);
    return { rebate: rebateCents / 100 + 0, bands };
  }
  return { calculateQuarterlyRebate };
})()

