build.unitScript:
test("purchases of 60,000.00 earn a rebate of 1,100.00 split over the 0%, 2% and 3% bands", () => {
  const result = code.calculateQuarterlyRebate({ quarterlyPurchases: 6e4 });
  assert.equal(result.rebate, 1100);
  assert.deepEqual(result.bands, [
    { rate: 0, portion: 1e4, amount: 0 },
    { rate: 0.02, portion: 4e4, amount: 800 },
    { rate: 0.03, portion: 1e4, amount: 300 }
  ]);
});
test("purchases of exactly 10,000.00 earn no rebate", () => {
  const result = code.calculateQuarterlyRebate({ quarterlyPurchases: 1e4 });
  assert.equal(result.rebate, 0);
  assert.equal(result.bands[1].portion, 0);
  assert.equal(result.bands[2].portion, 0);
});
test("purchases of exactly 50,000.00 earn 800.00 from the 2% band and nothing from the 3% band", () => {
  const result = code.calculateQuarterlyRebate({ quarterlyPurchases: 5e4 });
  assert.equal(result.rebate, 800);
  assert.equal(result.bands[1].portion, 4e4);
  assert.equal(result.bands[2].portion, 0);
  assert.equal(result.bands[2].amount, 0);
});
test("purchases of 10,000.50 earn a rebate of 0.01", () => {
  const result = code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.5 });
  assert.equal(result.rebate, 0.01);
  assert.equal(result.bands[1].portion, 0.5);
});
test("rebates that are not exact half cents round to the nearest cent", () => {
  assert.equal(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.2 }).rebate, 0);
  assert.equal(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.3 }).rebate, 0.01);
  assert.equal(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.8 }).rebate, 0.02);
});
test("unknown fields and missing or non-finite purchases are rejected with the contract messages", () => {
  assert.throws(() => code.calculateQuarterlyRebate({ quarterlyPurchases: 6e4, region: "north" }), /^Error: unknown field: region$|unknown field: region/);
  assert.throws(() => code.calculateQuarterlyRebate({}), /invalid field: quarterlyPurchases/);
  assert.throws(() => code.calculateQuarterlyRebate({ quarterlyPurchases: "60000" }), /invalid field: quarterlyPurchases/);
  assert.throws(() => code.calculateQuarterlyRebate({ quarterlyPurchases: NaN }), /invalid field: quarterlyPurchases/);
  assert.throws(() => code.calculateQuarterlyRebate({ quarterlyPurchases: Infinity }), /invalid field: quarterlyPurchases/);
});

